    24	        ...rest
    25	    }: PressableWithSecondaryInteractionProps,
    26	    ref: PressableRef,
    27	) {
    28	    const styles = useThemeStyles();
    29	    const StyleUtils = useStyleUtils();
    30	    const pressableRef = useRef<HTMLDivElement | null>(null);
    31	
    32	    const executeSecondaryInteraction = (event: GestureResponderEvent) => {
    33	        if (DeviceCapabilities.hasHoverSupport() && !enableLongPressWithHover) {
    34	            return;
    35	        }
    36	        if (withoutFocusOnSecondaryInteraction && pressableRef.current) {
    37	            pressableRef.current.blur();
    38	        }
    39	        onSecondaryInteraction?.(event);
    40	    };
