    43	        if (!pressableRef.current) {
    44	            return;
    45	        }
    46	
    47	        if (ref) {
    48	            if (typeof ref === 'function') {
    49	                ref(pressableRef.current);
    50	            } else if (typeof ref === 'object') {
    51	                // eslint-disable-next-line no-param-reassign
    52	                ref.current = pressableRef.current;
    53	            }
    54	        }
    55	
    56	        const element = pressableRef.current;
    57	
    58	        /**
    59	         * @param event - A right-click MouseEvent.
    60	         * https://developer.mozilla.org/en-US/docs/Web/API/Element/contextmenu_event
    61	         */
    62	        const executeSecondaryInteractionOnContextMenu = (event: MouseEvent) => {
    63	            if (!onSecondaryInteraction) {
    64	                return;
    65	            }
    66	
    67	            event.stopPropagation();
